var toggle_favorite_default = defineTool4({
  name: "toggle_favorite",
  title: "Ajouter/retirer un favori",
  description: "Ajoute ou retire un enseignement des favoris de l'utilisateur connect\xE9.",
  inputSchema: {
    teaching_id: z3.string().uuid().describe("UUID de l'enseignement \xE0 basculer.")
  },
  annotations: { readOnlyHint: false, idempotentHint: false },
  handler: async ({ teaching_id }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Authentification requise." }], isError: true };
    }
    const supabase = supabaseForUser4(ctx);
    const userId = ctx.getUserId();
    const { data: existing } = await supabase.from("favorites").select("id").eq("user_id", userId).eq("teaching_id", teaching_id).maybeSingle();
    if (existing) {
      const { error: error2 } = await supabase.from("favorites").delete().eq("id", existing.id);
      if (error2) return { content: [{ type: "text", text: error2.message }], isError: true };
      return {
        content: [{ type: "text", text: "Favori retir\xE9." }],
        structuredContent: { favorited: false }
      };
    }
    const { error } = await supabase.from("favorites").insert({ user_id: userId, teaching_id });
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: "Ajout\xE9 aux favoris." }],
      structuredContent: { favorited: true }
    };
  }
});

